CustomField.formula:
IF(
/*If Account is Country Parent, stores Primary_Local_Market_Rep_1__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Primary_Local_Market_Rep_1__c ,
IF(
/*If Account is Sales site, stores Country Parent Account's Primary_Local_Market_Rep_1__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.Primary_Local_Market_Rep_1__c,Primary_Local_Market_Rep_1__c))
